	// d=1: s must be odd, s>1. s=3,5,7,9,...
	//   x = 1*3=3, 1*5=5, 1*7=7, 1*9=9, ...
	// d=2: s must be even, s>2. s=4,6,8,...
	//   x = 2*4=8, 2*6=12, 2*8=16, ...
	// d=3: s must be odd, s>3. s=5,7,9,...
	//   x = 3*5=15, 3*7=21, ...
	// d=4: s must be even, s>4. s=6,8,10,...
	//   x = 4*6=24, 4*8=32, ...

