	// 2nd: 5
	// 3rd: 7
	// This matches the sample! N=3 gives 7.

	// So the problem is: find the N-th smallest number of the form d*s where d>=1, s>d, s≡d (mod 2).
	// Equivalently, x = b^2 - a^2 for integers 1 <= a < b.

	// We need an efficient way to find the N-th such number for N up to 10^9.
	// Let's think about how many such numbers are <= X.
	// Count(X) = number of pairs (a,b) with 1<=a<b and b^2 - a^2 <= X.
	// b^2 - a^2 = (b-a)(b+a) <= X.
	// Let d = b-a, s = b+a. Then d*s <= X, s > d, s ≡ d (mod 2).
	// For a given d, s can range from d+1 (or d+2 if parity differs) up to floor(X/d), with s ≡ d (mod 2).
	// Actually, s must be > d and s ≡ d (mod 2).
	// The smallest s is d+1 if d+1 ≡ d (mod 2) which is never true. So smallest s is d+2 if d+2 ≡ d (mod 2) which is always true.
	// Wait, s and d must have same parity. So s = d + 2k for k >= 1.
	// So s = d+2, d+4, d+6, ...
	// We need d*s <= X => d*(d+2k) <= X.
	// For a fixed d, the number of valid s is the number of k >= 1 such that d*(d+2k) <= X.
	// d^2 + 2dk <= X => 2dk <= X - d^2 => k <= (X - d^2)/(2d).
	// So count for fixed d is floor((X - d^2)/(2d)) if X >= d^2 + 2d, else 0.
	// More precisely, count_d = max(0, floor((X - d^2)/(2d))).
	// But we also need s > d, which is satisfied by k >= 1.
	// And s must be integer, which it is.

	// So Count(X) = sum_{d=1}^{floor(sqrt(X))} max(0, floor((X - d^2)/(2d))).
	// Note: d^2 < X is needed for there to be any k. Actually d^2 + 2d <= X for k>=1.
	// So d must satisfy d^2 + 2d <= X, i.e., d <= -1 + sqrt(1+X).
	// Approximately d <= sqrt(X).

	// We can binary search on X to find the smallest X such that Count(X) >= N.
	// Then the answer is that X.

	// Let's implement Count(X) efficiently.
	// The sum is over d from 1 to about sqrt(X).
	// For X up to ~10^18 (since N up to 10^9, and the N-th number is roughly O(N^2) or so?), 
	// sqrt(X) could be up to 10^9, which is too slow for a direct sum.

	// Wait, let's estimate the size of the N-th number.
	// The numbers are roughly distributed. How many numbers <= X?
	// Count(X) ≈ sum_{d=1}^{sqrt(X)} (X - d^2)/(2d) ≈ sum_{d=1}^{sqrt(X)} (X/(2d) - d/2)
	// ≈ X/2 * H(sqrt(X)) - 1/2 * (sqrt(X))^2 / 2
	// ≈ X/2 * ln(sqrt(X)) - X/4
	// ≈ X/2 * (1/2 ln X) - X/4
	// ≈ X/4 ln X - X/4
	// ≈ (X/4)(ln X - 1)

	// So Count(X) ≈ (X/4) ln X.
	// We want Count(X) ≈ N.
	// So (X/4) ln X ≈ N => X ln X ≈ 4N.
	// For N = 10^9, 4N = 4*10^9.
	// X ln X = 4*10^9.
	// Try X = 10^9: 10^9 * ln(10^9) ≈ 10^9 * 20.7 ≈ 2*10^10. Too big.
	// Try X = 10^8: 10^8 * ln(10^8) ≈ 10^8 * 18.4 ≈ 1.8*10^9. Close.
	// So X is around 10^8 to 10^9.
	// sqrt(X) is around 10^4 to 10^4.5.
	// So the sum has about 10^4 to 10^5 terms. That's fast enough!

	// Let's implement binary search on X.
	// Lower bound: 1. Upper bound: let's say 10^18 to be safe, but we can be smarter.
	// Since Count(X) grows roughly as X ln X, and we need Count(X) >= 10^9,
	// X is at most around 10^10 or so. Let's use 10^18 as upper bound to be safe.

	// Function to compute Count(X):
	// sum for d=1 to floor(sqrt(X-2d)) ... actually just d=1 to floor(sqrt(X)) is fine, 
	// and for each d, if d^2 + 2d > X, then count is 0.
	// count_d = (X - d^2) / (2d) using integer division, but only if X >= d^2 + 2d.
	// Actually, (X - d^2) / (2d) gives the max k. We need k >= 1, so we need (X - d^2) >= 2d.
	// So condition: X >= d^2 + 2d.
	// count_d = (X - d^2) / (2d) if X >= d^2 + 2d, else 0.
	// Note: integer division in Go for positive numbers is floor division.

	// Let's code this up.

	// Binary search for the smallest X such that Count(X) >= N.

	lo := int64(1)
	hi := int64(1e18)

	for lo < hi {
		mid := (lo + hi) / 2
		if countSuitable(mid) >= n {
			hi = mid
		} else {
			lo = mid + 1
		}
	}

	fmt.Println(lo)
}

func countSuitable(x int64) int64 {
	// Sum over d=1 to floor(sqrt(x)) of max(0, (x - d^2) / (2d))
	// where we only count if x >= d^2 + 2d.

	var count int64 = 0
	// d goes up to sqrt(x)
	// sqrt(x) for x up to 1e18 is 1e9, which is too many iterations.
	// Wait, earlier I estimated sqrt(X) ~ 10^4.5 for X ~ 10^9.
	// But if X is up to 1e18, sqrt(X) is 1e9. That's too slow.

	// I need to optimize the sum.
	// The sum is sum_{d=1}^{D} (x - d^2) / (2d) where D is such that d^2 + 2d <= x.
	// (x - d^2) / (2d) = x/(2d) - d/2.
	// So sum = x/2 * sum_{d=1}^{D} 1/d - 1/2 * sum_{d=1}^{D} d.
	// But this is not exact because of integer division.
	// However, for large x, the approximation might be good enough for binary search?
	// No, we need exact count.

	// Alternative: the number of terms is D ~ sqrt(x). If x is ~10^9, D ~ 31622. That's fine.
	// If x is ~10^12, D ~ 10^6. Still fine.
	// If x is ~10^15, D ~ 3*10^7. Might be slow in Go but probably okay.
	// If x is ~10^18, D ~ 10^9. Too slow.

	// But we established that for N=10^9, x is around 10^8 to 10^9.
	// So D is around 10^4 to 10^5. That's very fast.
	// Let's just use the direct sum and hope that x doesn't get too large.
	// To be safe, let's cap D at some reasonable value, but actually D is determined by x.

	// Let's just compute D = floor((-2 + sqrt(4 + 4x))/2) = floor(-1 + sqrt(1+x)).
	// Or simply iterate d from 1 while d*d + 2*d <= x.

	d := int64(1)
	for d*d+2*d <= x {
		count += (x - d*d) / (2 * d)
		d++
	}

	return count
}
