func countSuitable(x int64) int64 {
	if x < 3 {
		return 0
	}
	oddCount := (x - 1) / 2
	mult4Count := int64(0)
	if x >= 8 {
		mult4Count = x/4 - 1
	}
	return oddCount + mult4Count
