func count(M int64) int64 {
	if M < 3 {
		return 0
	}
	oddCount := (M - 1) / 2
	evenCount := M / 4
	if evenCount > 0 {
		evenCount--
	} else {
		evenCount = 0
	}
	return oddCount + evenCount
}
